    body: "云跑得很慢，从窗外这头挪到那头，像在散步。小猪把自己蜷成小小的一团，先给她焐着被角。小金毛把玩具骨头一只只排成小队，摆得整整齐齐。有人一起陪着待着，怕的小事就少了很多。被子里暖得刚刚好，不闷也不凉。两个人互相让着一点位置，谁也不挤谁。旁边的呼吸一起一伏，慢慢合上了同一个节奏。她轻轻舒了口气，像是把胸口那块小石头放下了。今天辛苦啦，剩下的交给明天慢慢来。"
