    body: "抱着靠垫坐了一会儿，整个人慢慢放松下来。小猪小声念叨明天要做的两三件小事，念着念着就轻了。小金毛把爪子搭在被沿，陪着不闹也不催。一句轻轻的“辛苦了”，让肩膀卸下一点重量。台灯的光落在被面上，像铺了一层薄薄的蜜色。一小片安静落下来，把今天的烦心事挡在了外面。耳边的声音越来越远，只剩身边温热的陪伴。枕头被拍了两下，软乎乎地陷下去，刚好托住脖子。所有小紧绷都松开，只留下暖暖的余温。"
