    body: "屋里的绿植叶子垂着，也像是要准备休息了。小猪慢慢帮她把松开的被角掖到肩膀下面。小金毛用耳朵轻轻碰碰她的手指，软乎乎的。一句轻轻的“辛苦了”，让肩膀卸下一点重量。月光薄得像一层纱，轻轻铺在地板上。手边的小物被归拢好，秩序感让人安心。耳边的声音越来越远，只剩身边温热的陪伴。枕头被拍了两下，软乎乎地陷下去，刚好托住脖子。今天辛苦啦，剩下的交给明天慢慢来。"
