    body: "闷了一整天，这会儿终于能靠着垫子喘口气。小猪把桌上的小绒线团滚来滚去，玩得不亦乐乎。小金毛守在旁边，她一抬头就对上一双亮晶晶的眼睛。她的呼吸慢慢变匀，身边的陪伴是结实的。抱枕被压出一个舒服的凹陷，贴着肩背。枕头被拍了两下，软乎乎地陷下去，刚好托住脖子。想起白天某个小小的笑，嘴角也松了下来。她翻了个身，被子顺着姿势回到肩上，不用自己去拉。今天这点小开心，就好好收进口袋里。"
