    body: "晴天里云朵一朵一朵走得很慢，像在慢悠悠逛街。小猪把散在桌上的便签纸叠好，压到镇纸下面。小金毛学她的样子深呼吸一次，慢慢吐出热气。有人一起陪着待着，怕的小事就少了很多。台灯的光落在被面上，像铺了一层薄薄的蜜色。两个人互相让着一点位置，谁也不挤谁。耳边的声音越来越远，只剩身边温热的陪伴。枕头被拍了两下，软乎乎地陷下去，刚好托住脖子。身边有他们陪着，心里就不慌也不空。"
